with p as (
  select * from events where event_name='purchase'
  qualify row_number() over (partition by event_id order by ingested_at) = 1
), o as (
  select p.order_id, cast(timezone('America/Los_Angeles', timezone('UTC', p.event_ts)) as date) as order_date, u.is_internal
  from p left join users u using (user_id)
)
select count(distinct order_id) filter (where is_internal = false) as orders,
  count(*) filter (where is_internal is null) as orphan_orders
from o where order_date between date '2025-03-24' and date '2025-03-30'

